import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const kind of ["w9", "insurance_certificate", "contract"] as const) {
    const response = await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
      data: { decision: "approve" },
    });
    const body = await expectStatus(response, 200);
    expect(body.status).toBe("approved");
  }

  // Assert
  await expect
    .poll(async () => (await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status, {
      message: "vendor is approved once every extraction is approved",
      timeout: 15_000,
    })
    .toBe("approved");

  await expect
    .poll(
      async () => {
        const trail = await expectStatus<{ items: { action: string }[] }>(
          await reviewer.get(`/api/vendors/${vendor.id}/audit`),
          200,
        );
        return trail.items.map((event) => event.action);
      },
      { message: "audit trail records vendor.approved", timeout: 15_000 },
    )
    .toContain("vendor.approved");
});
